use serde_json::{Value, json};

#[test]
fn malformed_lines_are_invalid_requests() {
    let mut session = Session::new();
    let lines: [&[u8]; 9] = [
        b"",
        b"   ",
        b"not json",
        b"[1]",
        b"\"CreateQueue\"",
