#[test]
fn receipt_handle_errors() {
    let mut session = Session::new();
    session.create("q", json!({"VisibilityTimeout": 5}));
    session.create("other", json!({}));
    session.send("q", "a");
    let handle = session.receive("q")[0]["ReceiptHandle"].clone();
    let delete = |queue: &str, handle: Value| {
        json!({"Command": "DeleteMessage", "QueueName": queue, "ReceiptHandle": handle})
    };
    for never_issued in ["r-01", "R-1", "r-1 ", "r-2", "r-0", "x", "", "r-99999999999999999999"] {
        assert_eq!(session.err(delete("q", json!(never_issued))), "ReceiptHandleInvalid", "{never_issued:?}");
    }
    assert_eq!(session.err(delete("other", handle.clone())), "ReceiptHandleExpired");
    session.tick(5);
    assert_eq!(session.err(delete("q", handle.clone())), "ReceiptHandleExpired");
    let newest = session.receive("q")[0]["ReceiptHandle"].clone();
    assert_eq!(newest, json!("r-2"));
    assert_eq!(session.err(delete("q", handle.clone())), "ReceiptHandleExpired");
    assert_eq!(session.err(delete("missing", handle)), "QueueDoesNotExist");
    session.ok(delete("q", newest.clone()));
    assert_eq!(session.err(delete("q", newest)), "ReceiptHandleExpired");
    assert_eq!(session.counts("q"), json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

